export type TrafficMode = 'static' | 'dynamic'

export type NetworkNode = {
  id: number
  lat: number
  lng: number
  node_type: 'depot' | 'customer' | 'intersection'
}

export type NetworkEdge = {
  u: number
  v: number
  distance_km: number
  traffic_state: 'free_flow' | 'moderate' | 'congested'
  congestion: number
}

export type Traversal = {
  vehicle: number
  u: number
  v: number
  start_time_min: number
  traffic_state: 'free_flow' | 'moderate' | 'congested'
  congestion: number
  travel_time_min: number
}

export type SimulationResult = {
  scenario: { seed: number; nodes: number; edges: number; origin: number; depot: number; customers: number[]; vehicles: number; traffic_mode: TrafficMode }
  algorithm: { name: string; runtime_ms: number; iterations: number; objective_evaluations: number; convergence_percent: number }
  route: number[]
  routes: number[][]
  customer_routes: number[][]
  metrics: { distance_km: number; travel_time_min: number; average_speed_kmh: number; total_cost: number; nodes_visited: number; fitness: number; feasible: boolean; simulation_duration_min: number }
  network: { nodes: NetworkNode[]; edges: NetworkEdge[] }
  traffic: { mode: TrafficMode; states: Traversal[]; timeline: Traversal[] }
  convergence_history: { evaluations: number; best_fitness: number }[]
}

export type ComparisonResult = {
  scenario: { seed: number; nodes: number; edges: number; traffic_mode: TrafficMode }
  runtime_ms: number
  results: { name: string; distance_km: number; travel_time_min: number; total_cost: number; fitness: number; feasible: boolean; runtime_ms: number }[]
}

const apiUrl = (process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000').replace(/\/$/, '')

async function request<T>(path: string, payload: object): Promise<T> {
  const response = await fetch(`${apiUrl}${path}`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
  })
  const body = await response.json().catch(() => null)
  if (!response.ok) throw new Error(body?.detail || `API request failed (${response.status})`)
  return body as T
}

export function runSimulation(payload: { algorithm: string; traffic_mode: TrafficMode; nodes: number; vehicles: number; seed: number }) {
  return request<SimulationResult>('/api/simulation/run', payload)
}

export function compareAlgorithms(payload: { traffic_mode: TrafficMode; nodes: number; vehicles: number; seed: number }) {
  return request<ComparisonResult>('/api/simulation/compare', payload)
}
